const orderLabels={new:'Хүсэлт хүлээн авсан',reviewing:'Шалгаж байна',quoted:'Үнийн санал ирсэн',confirmed:'Баталгаажсан',shipping:'Хүргэлтэд',erenhot:'Эрээн агуулахад ирсэн',erenhot_ready:'Улаанбаатар луу гарахад бэлэн',erenhot_dispatched:'Замын-Үүд рүү явж байна',zamyn_uud:'Замын-Үүдэд',ulaanbaatar:'Улаанбаатарт хүлээн авсан',ulaanbaatar_unsorted:'Улаанбаатар агуулахад ирсэн · ангилж байна',ready_pickup:'Агуулахаас авахад бэлэн',ready_delivery:'Хүргэлтэд гаргахад бэлэн',out_for_delivery:'Хүргэлтэд гарсан',completed:'Хүлээлгэн өгсөн',cancelled:'Цуцалсан'};
function orderStatusLabel(o,status=o.status){if(status==='quoted'&&o.type==='checkout')return 'Төлбөр хүлээж байна';const names=o.warehouse_names;if(names){if(status==='erenhot')return names.erenhot+' · бараа ирсэн';if(status==='erenhot_ready')return names.ulaanbaatar+' руу гарахад бэлэн';if(status==='ulaanbaatar'||status==='ulaanbaatar_unsorted')return names.ulaanbaatar+(status==='ulaanbaatar_unsorted'?' · ангилж байна':' · хүлээн авсан');}return orderLabels[status]||status;}

storeServer.orders=async(offset=0)=>{try{
  await customerAccount.refresh();const user=customerAccount.user;
  const result=user?await shopApi('customer-orders&offset='+offset):{orders:[],more:false};
  const ownIds=new Set(result.orders.map(o=>o.id));const guest=savedRequests().filter(r=>!ownIds.has(r.id));
  const card=o=>`<article class="draft-card"><h3>${esc(o.title)}</h3><p>${esc(o.id)}${o.status?' · '+esc(orderStatusLabel(o)):''}</p><button class="text-button" data-server-order="${esc(o.id)}">Харах →</button></article>`;
  openModal('Миний захиалгууд',`<p class="modal-intro">${user?'Бүртгэлтэй холбогдсон захиалгууд бүх төхөөрөмжөөс харагдана.':'Нэвтэрч орсноор захиалгуудаа өөр төхөөрөмжөөс харах боломжтой.'}</p>${!user?'<button class="button blue" data-action="account">Нэвтрэх / Бүртгүүлэх</button>':''}${result.orders.map(card).join('')}${user&&(offset>0||result.more)?`<div class="form-actions">${offset>0?`<button class="button outline" data-orders-offset="${Math.max(0,offset-20)}">Өмнөх</button>`:''}${result.more?`<button class="button outline" data-orders-offset="${offset+20}">Дараах</button>`:''}</div>`:''}${!offset&&guest.length?`<h3 class="account-section-title">Энэ хөтчийн хүсэлтүүд</h3>${guest.map(r=>`<article class="draft-card"><h3>${esc(r.title)}</h3><p>${esc(r.id)}</p><button class="text-button" data-server-order="${esc(r.id)}">Харах →</button>${user?`<button class="text-button" data-claim-order="${esc(r.id)}">Бүртгэлдээ холбох</button>`:''}</article>`).join('')}`:''}${!result.orders.length&&!guest.length?'<div class="empty-state"><h3>Захиалга алга</h3><p>Каталогоос бараа сонгон хүсэлт илгээгээрэй.</p></div>':''}${state.drafts.length?`<p class="modal-intro">Энэ хөтөчид серверт илгээгээгүй ${state.drafts.length} ноорог бий.</p>`:''}`);
}catch(e){toast(e.message);}};
function bankUrl(v){try{const u=new URL(v);return ['https:','qpaywallet:','khanbank:','statebankmongolia:','xacbank:','tdbbank:','socialpay-payment:','most:','nibank:','ckbank:','capitronbank:','bogdbank:','transbank:','mbank:','ard:','toki:','arig:','monpay:','hipay:','tdbwallet:','sono:','payon:','tino:','pass:'].includes(u.protocol)?u.href:null;}catch{return null;}}
async function viewServerOrder(id,requestInvoice=false){const r=savedRequests().find(x=>x.id===id)||{id,token:''};try{const {order:o}=await shopApi(requestInvoice?'invoice':'order-get',{id:r.id,token:r.token});openModal('Хүсэлт '+o.id,`<p class="modal-intro">${esc(o.title)}</p><div class="info-box"><strong>${esc(orderStatusLabel(o))}</strong><br>${o.paid?'QPay төлбөр баталгаажсан':'Төлбөр хүлээн аваагүй'}${o.payment_due&&o.status==='quoted'&&!o.paid?'<br>Төлөх хугацаа: '+esc(new Date(o.payment_due).toLocaleString('mn-MN'))+' хүртэл':''}${o.cancel_reason==='payment_timeout'?'<br>Төлбөрийн хугацаа дууссан тул цуцлагдсан.':''}</div><p class="product-price">${o.type==='checkout'?'Урьдчилан төлөх: '+money(o.amount):o.amount?'Хүргэлт орсон нийт: '+money(o.amount):'Үнийн санал хүлээгдэж байна'}</p>${shippingOrderHtml(o)}${o.demo?'<p class="modal-intro">Жишээ бараа тул төлбөр авахгүй.</p>':''}${o.invoice?.state==='ready'&&!o.paid?`<div style="text-align:center;margin:20px 0"><img style="width:230px;margin:auto" alt="QPay төлбөрийн QR" src="data:image/png;base64,${esc(o.invoice.qr_image.replace(/[^a-zA-Z0-9+/=]/g,''))}"></div><div class="bank-links" aria-label="Банкны аппаар төлөх">${(o.invoice.urls||[]).filter(x=>bankUrl(x.link)).map(x=>`<a class="button outline" href="${esc(bankUrl(x.link))}" rel="noopener noreferrer">${String(x.logo||'').startsWith('https://')?`<img src="${esc(x.logo)}" alt="" width="24" height="24" loading="lazy" referrerpolicy="no-referrer">`:''}<span>${esc(x.description||x.name)}</span></a>`).join('')}</div>`:''}<div class="form-actions"><button class="button outline" data-server-order="${esc(o.id)}">Төлөв шинэчлэх</button>${o.status==='quoted'&&!o.paid&&!o.demo&&qpayEnabled?`<button class="button blue" data-invoice="${esc(o.id)}">QPay нэхэмжлэл харах</button>`:''}</div>${!qpayEnabled?'<p class="modal-intro">QPay холболт хараахан идэвхжээгүй.</p>':''}`);}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ordersOffset!==undefined){await storeServer.orders(Number(b.dataset.ordersOffset));return;}if(b.dataset.claimOrder){b.disabled=true;try{const r=savedRequests().find(x=>x.id===b.dataset.claimOrder);if(!r)return;await shopApi('customer-claim-order',{id:r.id,token:r.token});localStorage.setItem(REQUESTS_KEY,JSON.stringify(savedRequests().filter(x=>x.id!==r.id)));await storeServer.orders();toast('Захиалга бүртгэлтэй холбогдлоо');}catch(err){toast(err.message);}finally{b.disabled=false;}return;}const id=b.dataset.serverOrder||b.dataset.invoice;if(id){b.disabled=true;try{await viewServerOrder(id,!!b.dataset.invoice);}finally{b.disabled=false;}}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='server-cart-form')return;e.preventDefault();const submit=f.querySelector('[type="submit"]');submit.disabled=true;try{if(!customerAccount.require())return;const fields=Object.fromEntries(new FormData(f));fields.type='cart';fields.items=state.cart.map(x=>({...x}));f.dataset.requestToken ||= Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');fields.token=f.dataset.requestToken;fields.require_account=true;const result=await shopApi('order-create',fields);const requests=savedRequests().filter(x=>x.id!==result.order.id);requests.unshift({id:result.order.id,token:fields.token,title:fields.title});try{if(!window.customerAccount?.user)localStorage.setItem(REQUESTS_KEY,JSON.stringify(requests.slice(0,100)));}catch{throw Error('Хүсэлт серверт ирсэн боловч хөтөч хадгалах боломжгүй. Захиалгын дугаар: '+result.order.id);}state.cart=[];persist();toast('Хүсэлт амжилттай илгээгдлээ');storeServer.orders();}catch(e){const error=f.querySelector('#request-error');if(error)error.textContent=e.message;}finally{submit.disabled=false;}});
window.catalogReady=(async()=>{if(!['http:','https:'].includes(location.protocol))return;try{const result=await shopApi('catalog');if(!Array.isArray(result.products))return;localProductsEnabled=result.local_products_enabled===true;document.querySelectorAll('[data-filter="local"]').forEach(el=>el.hidden=true);products.splice(0,products.length,...result.products);Object.assign(state,readState());qpayEnabled=result.qpay;storeServer.shipping=result.shipping;document.querySelectorAll('[data-image-search]').forEach(el=>el.hidden=!(result.supplier===true&&result.shipping?.image_search_enabled===true));storeServer.customer=result.customer;window.customerAccount?.setUser(result.customer);storeServer.ready=true;helpContent.help.html='<p class="modal-intro">Бараагаа сонгоод сагслан, QPay-ээр шууд төлнө.</p><ol class="help-list"><li>Бараа, хувилбар, тоо ширхэгээ сонгоно.</li><li>Сагсандаа нэмээд «Төлбөр тооцох» дарна. Барааны үнэ, үйлчилгээний дүн шууд гарна.</li><li>QPay-ээр 24 цагийн дотор төлнө. Хятад доторх хүргэлт, олон улсын каргог Улаанбаатарт ирэхэд бодит дүнгээр тооцож төлнө.</li><li>Бараагаа Улаанбаатар дахь каргоны хаягаас авах кодоороо авна.</li></ol>'+pickupHtml()+'<div class="info-box">'+(qpayEnabled?'Үнийн санал баталгаажмагц QPay QR эсвэл банкны апп-аар төлнө.':'QPay холболт одоогоор идэвхгүй байна.')+' Жишээ бараагаар төлбөр авахгүй.</div>';renderProducts();updateCounts();$('#catalog .sample-label').textContent='QPay · Улаанбаатарт хүргэлт';$('.preview-notice').innerHTML=icon('shield')+'<div><strong>Сагслаад шууд худалдан авна.</strong> '+esc(commerceUI.paymentText(result.shipping))+'</div>';helpContent.privacy.html='<p class="detail-copy">Вэб сайт Google Analytics болон Meta Pixel ашиглан хуудасны хандалт, зар сурталчилгааны үр дүнг хэмжинэ. Хуудасны URL, хөтөч/төхөөрөмжийн мэдээлэл болон cookie танигчид эдгээр үйлчилгээнд дамжиж болно. Cookie болон tracking-ийг хөтөчийн тохиргоогоор хязгаарлаж болно.</p><p class="modal-intro">Сагс, хадгалсан бараа хөтөчид хадгалагдана. Нэвтэрсэн үед өөр төхөөрөмжөөс үргэлжлүүлэхийн тулд таны бүртгэлд мөн хадгалагдаж, бүртгэлээс гарахад энэ төхөөрөмжөөс цэвэрлэгдэнэ. Бүртгэлийн нэр, имэйл, утас, хүргэлтийн хаяг болон захиалга GOStore-ийн серверт хадгалагдана. Зургаар хайхад сонгосон зургийг TaoWorld-д дамжуулна; GOStore дээр хайлтын зургийг 7 хоног хүртэл хадгална. Профайлд нэвтрэх нууц үгийг hash хэлбэрээр хадгална. Нэвтэрсэн хэрэглэгч өөрийн захиалгыг, админ захиалгын хүргэлтийн мэдээллийг харна. Эрээн агуулахын менежер хүлээн авагчийн нэр, код, бараа болон багцыг харна. Улаанбаатар агуулахын менежер барааг ангилж хүлээлгэн өгөхдөө холбоо барих утас, хүргэлтийн хаягийг ашиглана.</p><p class="detail-copy">Бүртгэлтэй холбогдсон захиалгаа өөр төхөөрөмжөөс нэвтэрч харж болно. Зочны хүсэлтийн түлхүүр зөвхөн энэ хөтөчид хадгалагдана. Нууц үг, картын мэдээллийг тэмдэглэлд оруулахгүй.</p>';}catch{/* A static preview has no PHP endpoint. */}})();
